import calendar

def parse_uk_date(text):
    s = (text or "").strip()
    names = {}
    for i in range(1, 13):
        names[calendar.month_name[i].lower()] = i
        names[calendar.month_abbr[i].lower()] = i
    day = month = year = None
    for sep in "/-.":
        if sep in s:
            parts = s.split(sep)
            if len(parts) != 3 or not all(p.isdigit() and p.isascii() for p in parts):
                return None
            if not (1 <= len(parts[0]) <= 2 and 1 <= len(parts[1]) <= 2 and len(parts[2]) in (2, 4)):
                return None
            day, month, year = int(parts[0]), int(parts[1]), int(parts[2])
            if len(parts[2]) == 2:
                year += 2000
            break
    else:
        parts = s.split(" ")
        if len(parts) != 3:
            return None
        d = parts[0].lower()
        for suf in ("st", "nd", "rd", "th"):
            if d.endswith(suf):
                d = d[:-2]
                break
        if not (d.isdigit() and 1 <= len(d) <= 2 and parts[2].isdigit() and len(parts[2]) == 4):
            return None
        month = names.get(parts[1].lower())
        if month is None:
            return None
        day, year = int(d), int(parts[2])
    if not (1 <= month <= 12) or year < 1:
        return None
    if not (1 <= day <= calendar.monthrange(year, month)[1]):
        return None
    return "%04d-%02d-%02d" % (year, month, day)

